"""Original matchingOptions markup and computed CSS; generated table names only."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];out=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text()
functions='\n'.join(s for s in src.splitlines()if s.startswith(('const esc=','const t=','function matchingOptions(')))
names=['demo.customers','archive.orders','demo.orders','example_schema.table_with_a_long_name_for_exact_wrapping']
cases=[]
for lang in ['ko','en']:
 for width in [240,342,442,492]:
  for name in names:
   busy=name=='demo.orders';note=(('다른 원본 테이블과 이미 대응되어 있습니다.','Already matched to another source table.')if busy else('원본과 이름이 같습니다.','Same name as the source.')if name=='demo.customers'else('이름 차이는 결과에 남습니다.','Name differences remain in the result.'))[lang=='en']
   states=[(False,False,False),(False,True,False)]if busy else[(False,False,False),(True,False,False),(False,True,False),(True,True,False),(True,False,True)]
   for selected,hover,focus in states:
    badge=(('사용 중','In use')if busy else('선택','Selected')if selected else('',''))[lang=='en'];cases.append(dict(id=f'{lang}-{width}-{len(cases)}',lang=lang,width=width,name=name,note=note,badge=badge,unavailable=busy,selected=selected,hover=hover,focus=focus))
css=(r/'docs/replica/source/original.css').read_text().replace(':hover','.fixture-hover').replace(':focus-visible','.fixture-focus');(out/'matchoption-original.css').write_text(css)
script="let lang='ko',state={maps:{}},modal={payload:'demo.customers',draft:''};"+functions+'\nconst cases='+json.dumps(cases,ensure_ascii=False)+''';for(const c of cases){lang=c.lang;state.maps={'demo.customers':'demo.customers','demo.orders':'demo.orders','demo.line_items':'demo.line_items'};if(!Object.hasOwn(state.maps,c.name)&&c.name!=='archive.orders')state.maps[c.name]='unmatched-example';modal.draft=c.selected?c.name:'';const template=document.createElement('div');template.innerHTML=matchingOptions();const e=[...template.querySelectorAll('.match-option')].find(e=>e.querySelector('input').value===c.name);const f=document.createElement('div');f.className='fixture';f.dataset.id=c.id;f.style.width=c.width+'px';e.classList.toggle('fixture-hover',c.hover);e.classList.toggle('fixture-focus',c.focus);e.querySelector('input').classList.toggle('fixture-focus',c.focus);e.querySelector('input').name=c.id;f.append(e);document.getElementById('fixtures').append(f)}function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const e=f.firstChild,r=e.getBoundingClientRect(),s=getComputedStyle(e),box=c=>{let b=c.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},input=e.querySelector('input'),name=e.querySelector('.mono'),note=e.querySelector('small'),badge=e.querySelector('b');return{id:f.dataset.id,width:r.width,height:r.height,radio:box(input),body:box(e.children[1]),name:box(name),note:box(note),badge:box(badge),nameText:name.textContent,noteText:note.textContent,badgeText:badge.textContent,selected:input.checked,disabled:input.disabled,bg:s.backgroundColor,border:s.borderColor,shadow:s.boxShadow,outline:s.outline,outlineOffset:s.outlineOffset,nameColor:getComputedStyle(name).color,badgeColor:getComputedStyle(badge).color}})}document.getElementById('matchoption-record').onclick=async()=>{await document.fonts.ready;const res=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:read()})});if(!res.ok)throw Error('Evidence failed');document.getElementById('matchoption-record').textContent='MatchOption recorded'};'''
(out/'matchoption.html').write_text('<!doctype html><meta charset="utf-8"><title>MatchOption · original isolation</title><link rel="stylesheet" href="matchoption-original.css"><style>body{min-width:1100px}.fixture{position:absolute;left:30px;top:30px}.fixture:not(:first-child){visibility:hidden;opacity:0;pointer-events:none}#matchoption-record{position:fixed;left:600px;top:300px}</style><button id="matchoption-record">Record MatchOption</button><div id="fixtures"></div><script>'+script+'</script>')
for p in [out/'matchoption-cases.json',r/'docs/replica/source/matchoption-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
print(len(cases),'literal MatchOption cases')
